const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);const W=1000,H=640;
let scale=1,playing=false,phase='menu',round=1,ours=0,theirs=0,money=800,side='attack',time=45,bomb=null,siteChoice='A',buyOpen=false,muted=false;
let player,allies=[],enemies=[],bullets=[],bricks=[],particles=[],keys={},mouse={x:700,y:320,down:false},last=0,fireWait=0,toastTimer=0,roundTimer=0,prep=7,roundOver=false;
const weapons={Pistol:{cost:0,mag:12,reserve:48,damage:34,rate:.32,color:'#d5b86b'},SMG:{cost:900,mag:28,reserve:84,damage:20,rate:.105,color:'#8ec778'},Rifle:{cost:2400,mag:24,reserve:72,damage:39,rate:.22,color:'#d8784f'},Shotgun:{cost:1700,mag:6,reserve:30,damage:16,rate:.68,color:'#d9a854'}};
let weapon='Pistol',ammo=12,reserve=48,armor=false;
const walls=[
 {x:0,y:0,w:1000,h:18},{x:0,y:622,w:1000,h:18},{x:0,y:0,w:18,h:640},{x:982,y:0,w:18,h:640},
 {x:185,y:18,w:20,h:150},{x:185,y:250,w:20,h:140},{x:185,y:470,w:20,h:152},
 {x:795,y:18,w:20,h:152},{x:795,y:250,w:20,h:140},{x:795,y:470,w:20,h:152},
 {x:340,y:18,w:18,h:100},{x:340,y:180,w:18,h:86},{x:340,y:390,w:18,h:75},{x:340,y:540,w:18,h:82},
 {x:642,y:18,w:18,h:100},{x:642,y:180,w:18,h:86},{x:642,y:390,w:18,h:75},{x:642,y:540,w:18,h:82},
 {x:205,y:158,w:135,h:18},{x:205,y:464,w:135,h:18},{x:660,y:158,w:135,h:18},{x:660,y:464,w:135,h:18},
 {x:380,y:140,w:110,h:18},{x:510,y:140,w:130,h:18},{x:380,y:482,w:110,h:18},{x:510,y:482,w:130,h:18},
 {x:430,y:18,w:18,h:60},{x:552,y:562,w:18,h:60},{x:430,y:562,w:18,h:60},{x:552,y:18,w:18,h:60}
];
const crates=[{x:270,y:278,w:57,h:54},{x:270,y:335,w:57,h:54},{x:390,y:256,w:55,h:55},{x:560,y:330,w:55,h:55},{x:705,y:277,w:50,h:60},{x:470,y:370,w:58,h:45},{x:84,y:279,w:58,h:56},{x:850,y:335,w:58,h:56},{x:441,y:202,w:40,h:38},{x:514,y:407,w:40,h:38}];
const sites={A:{x:120,y:320,r:45},B:{x:880,y:320,r:45}};
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));scale=Math.min(canvas.width/W,canvas.height/H);ctx.setTransform(scale,0,0,scale,(canvas.width-W*scale)/2,(canvas.height-H*scale)/2)}
new ResizeObserver(resize).observe(canvas);resize();
function rand(a,b){return a+Math.random()*(b-a)}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function showToast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),1800)}
function feed(t,c=''){const el=document.createElement('div');el.className=c;el.textContent='▶ '+t;$('feed').prepend(el);while($('feed').children.length>6)$('feed').lastChild.remove()}
function updateHUD(){ $('roundnum').textContent=String(round).padStart(2,'0');$('ourscore').textContent=ours;$('theirs').textContent=theirs;$('money').innerHTML='$'+money.toLocaleString()+' <small>PLASTIC COINS</small>';$('weaponname').textContent=weapon==='Pistol'?'Brick Pistol':'Brick '+weapon;$('ammo').textContent=`${ammo} / ${reserve}`;$('ammobar').style.width=(ammo/weapons[weapon].mag*100)+'%';$('armor').textContent=armor?'BRICK VEST':'NO ARMOR';$('sideLabel').textContent=side.toUpperCase();$('siteA').classList.toggle('active',siteChoice==='A');$('siteB').classList.toggle('active',siteChoice==='B');}
function setObjective(t){$('objective').textContent=t}
function newRound(){playing=true;phase='prep';roundOver=false;prep=7;time=45;bomb=null;side=round%2?'attack':'defend';siteChoice='A';bullets=[];particles=[];player={x:side==='attack'?92:500,y:320,angle:0,hp:100,alive:true,speed:178,kills:0};allies=[];enemies=[];
 for(let i=0;i<4;i++){allies.push(makeBot(side==='attack'?rand(65,145):rand(450,550),rand(250,390),'ally',i))}
 for(let i=0;i<5;i++){enemies.push(makeBot(side==='attack'?rand(830,925):rand(80,165),rand(240,400),'enemy',i))}
 if(side==='defend'){allies=allies.slice(0,4);enemies=enemies.slice(0,5)}
 $('start').classList.add('hidden');$('end').classList.add('hidden');$('buyfloat').classList.remove('hidden');setObjective('PREP PHASE · BUY YOUR BRICKS');$('phase').textContent='BUY PHASE · '+Math.ceil(prep)+'s';$('clock').textContent='0:45';updateHUD();feed(`Round ${round} — ${side} team deploys.`,'good');openShop(false);}
function makeBot(x,y,team,i){return{x,y,team,i,hp:100,alive:true,angle:0,speed:rand(66,86),cool:rand(.3,1),wander:rand(0,6),target:null}}
function openShop(auto=true){if(!playing)return;buyOpen=true;$('buy').classList.remove('hidden');renderShop();if(auto&&phase==='live'){} }
function renderShop(){ $('shopcash').textContent='Available studs: $'+money.toLocaleString()+' · pick one primary';const grid=$('shopgrid');grid.innerHTML='';for(const [name,w] of Object.entries(weapons)){if(name==='Pistol')continue;const b=document.createElement('button');b.className='buyitem';b.innerHTML=`<strong>▰ Brick ${name}</strong><span>$${w.cost} · ${w.mag} rounds</span>`;b.onclick=()=>{if(money<w.cost){showToast('NOT ENOUGH STUDS!');return}money-=w.cost;weapon=name;ammo=w.mag;reserve=w.reserve;updateHUD();renderShop();feed(`Bought a Brick ${name}.`,'good')};grid.appendChild(b)}const vest=document.createElement('button');vest.className='buyitem';vest.innerHTML='<strong>⬟ Brick Vest</strong><span>$650 · extra protection</span>';vest.onclick=()=>{if(armor){showToast('ALREADY ARMORED');return}if(money<650){showToast('NOT ENOUGH STUDS!');return}money-=650;armor=true;updateHUD();renderShop()};grid.appendChild(vest);const nade=document.createElement('button');nade.className='buyitem';nade.innerHTML='<strong>✹ Pop grenade</strong><span>$300 · blast nearby foes</span>';nade.onclick=()=>{if(money<300){showToast('NOT ENOUGH STUDS!');return}money-=300;player.grenades=(player.grenades||0)+1;updateHUD();renderShop();showToast('GRENADE ADDED · PRESS G')};grid.appendChild(nade)}
function closeShop(){buyOpen=false;$('buy').classList.add('hidden');if(phase==='prep'){} }
$('play').onclick=()=>newRound();$('closebuy').onclick=closeShop;$('buyfloat').onclick=()=>openShop();$('next').onclick=()=>{round++;money+=800;weapon='Pistol';ammo=12;reserve=48;armor=false;newRound()};
$('siteA').onclick=()=>{siteChoice='A';updateHUD()};$('siteB').onclick=()=>{siteChoice='B';updateHUD()};

