$('siteA').onclick=()=>{siteChoice='A';updateHUD()};$('siteB').onclick=()=>{siteChoice='B';updateHUD()};
function brickRect(x,y,w,h,color,seed=0){ctx.fillStyle='#0002';ctx.fillRect(x+3,y+5,w,h);ctx.fillStyle=color;ctx.fillRect(x,y,w,h);ctx.fillStyle='#ffffff18';ctx.fillRect(x+2,y+2,w-4,3);ctx.strokeStyle='#493d2d55';ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,w-1,h-1);const cols=Math.max(1,Math.floor(w/20)),rows=Math.max(1,Math.floor(h/20));for(let yy=0;yy<rows;yy++)for(let xx=0;xx<cols;xx++){let sx=x+(xx+.5)*w/cols,sy=y+(yy+.5)*h/rows;ctx.fillStyle='#0002';ctx.beginPath();ctx.ellipse(sx+1,sy+1,4.7,3.8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff30';ctx.beginPath();ctx.ellipse(sx,sy,4.5,3.5,0,0,Math.PI*2);ctx.fill()}}
function drawGround(){let g=ctx.createLinearGradient(0,0,1000,640);g.addColorStop(0,'#cfb98b');g.addColorStop(.52,'#b99f70');g.addColorStop(1,'#c7ae7d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // tiled brick-plaza ground
 for(let row=0;row<32;row++){for(let col=0;col<50;col++){let x=col*20+(row%2)*10,y=row*20;ctx.fillStyle=(row+col)%3===0?'#ab936a24':'#f3e3b51a';ctx.fillRect(x+1,y+1,18,18);ctx.beginPath();ctx.arc(x+10,y+10,2.4,0,Math.PI*2);ctx.fillStyle='#51472c1c';ctx.fill()}}
 // road lanes
 ctx.fillStyle='#897e6655';ctx.fillRect(18,270,964,100);ctx.fillStyle='#e2d2aa4b';ctx.fillRect(18,315,964,3);
 ctx.fillStyle='#897e6633';ctx.fillRect(455,18,90,604);ctx.fillStyle='#d9c99c33';ctx.fillRect(498,18,3,604);
 // decorative paving at sites
 for(const [name,s] of Object.entries(sites)){ctx.fillStyle='#eee0bc';ctx.beginPath();ctx.arc(s.x,s.y,52,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#968665';ctx.setLineDash([5,5]);ctx.lineWidth=2;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#685c44';ctx.font='bold 15px DM Mono';ctx.textAlign='center';ctx.fillText(name,s.x,s.y+5);brickRect(s.x-26,s.y+18,20,12,'#8e7450');brickRect(s.x+6,s.y+18,20,12,'#aa8e5e')}
 // walls and crates
 walls.forEach((v,i)=>brickRect(v.x,v.y,v.w,v.h,i%2?'#8f8067':'#9f8c6b'));
 crates.forEach((v,i)=>{brickRect(v.x,v.y,v.w,v.h,i%2?'#a2764c':'#b78755');ctx.strokeStyle='#65472e';ctx.lineWidth=3;ctx.strokeRect(v.x+5,v.y+5,v.w-10,v.h-10);ctx.beginPath();ctx.moveTo(v.x+7,v.y+7);ctx.lineTo(v.x+v.w-7,v.y+v.h-7);ctx.moveTo(v.x+v.w-7,v.y+7);ctx.lineTo(v.x+7,v.y+v.h-7);ctx.stroke()});
 // map label plates
 ctx.fillStyle='#242923aa';ctx.font='10px DM Mono';ctx.textAlign='left';ctx.fillText('A · OLD COURTYARD',38,215);ctx.fillText('B · MARKET ROW',827,215);ctx.fillStyle='#fff9';ctx.font='9px DM Mono';ctx.fillText('DUSTY BLOCKS  /  CITY CENTER',382,608);
}
function drawFigure(o,isPlayer=false){if(!o.alive)return;ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.angle||0);ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(2,7,13,9,0,0,Math.PI*2);ctx.fill();
 // legs / blocky torso
 ctx.fillStyle=isPlayer?'#526b54':o.team==='ally'?'#d57f48':'#416f7e';ctx.fillRect(-8,2,7,10);ctx.fillRect(2,2,7,10);ctx.fillStyle=isPlayer?'#d98349':o.team==='ally'?'#d2834c':'#6f9aa3';ctx.fillRect(-10,-8,20,14);ctx.strokeStyle='#2228';ctx.lineWidth=1;ctx.strokeRect(-10,-8,20,14);
 // arms and weapon
 ctx.fillStyle='#e8b657';ctx.fillRect(-13,-6,5,11);ctx.fillRect(8,-6,5,11);ctx.fillStyle='#3b413a';ctx.fillRect(4,-3,19,4);ctx.fillStyle='#81847a';ctx.fillRect(17,-4,8,2);
 // head, hair and silly belly accent
 ctx.fillStyle='#f0bd5a';ctx.beginPath();ctx.arc(0,-12,9,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#9a6f36';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle=isPlayer?'#443228':o.team==='enemy'?'#263b3b':'#554136';ctx.beginPath();ctx.arc(-1,-16,9,Math.PI,Math.PI*2);ctx.lineTo(9,-12);ctx.lineTo(3,-14);ctx.lineTo(0,-11);ctx.lineTo(-4,-14);ctx.closePath();ctx.fill();ctx.fillStyle='#34291f';ctx.fillRect(-4,-12,2,2);ctx.fillRect(3,-12,2,2);ctx.fillStyle='#8a432f';ctx.fillRect(-2,-8,5,1.5);
 if(o.hp<100){ctx.rotate(-(o.angle||0));ctx.fillStyle='#171d1acc';ctx.fillRect(-14,-29,28,4);ctx.fillStyle=o.team==='enemy'?'#e77d67':'#b5df72';ctx.fillRect(-14,-29,28*o.hp/100,4)}ctx.restore()}
function drawBomb(){if(!bomb)return;let b=bomb;ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.sin(performance.now()/140)*.08);ctx.fillStyle='#0006';ctx.fillRect(-10,4,22,17);brickRect(-11,-1,22,19,'#444a46');ctx.fillStyle='#e75f50';ctx.fillRect(-5,3,10,5);ctx.fillStyle='#e5d7b6';ctx.font='8px DM Mono';ctx.textAlign='center';ctx.fillText(Math.ceil(b.timer),0,15);ctx.restore()}
function draw(){ctx.clearRect(0,0,W,H);drawGround();if(player&&playing){allies.forEach(o=>drawFigure(o));enemies.forEach(o=>drawFigure(o));drawFigure(player,true);drawBomb();for(const p of particles){ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}}else{drawFigure({x:502,y:330,angle:-.5,alive:true,hp:100,team:'ally'},true);drawFigure({x:570,y:355,angle:2.6,alive:true,hp:100,team:'enemy'})}}

