function draw(){ctx.clearRect(0,0,W,H);drawGround();if(player&&playing){allies.forEach(o=>drawFigure(o));enemies.forEach(o=>drawFigure(o));drawFigure(player,true);drawBomb();for(const p of particles){ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}}else{drawFigure({x:502,y:330,angle:-.5,alive:true,hp:100,team:'ally'},true);drawFigure({x:570,y:355,angle:2.6,alive:true,hp:100,team:'enemy'})}}
function blocked(x,y,r=10){for(const v of walls.concat(crates)){if(x+r>v.x&&x-r<v.x+v.w&&y+r>v.y&&y-r<v.y+v.h)return true}return false}
