const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const tab = await fetch('http://127.0.0.1:9222/json/new?file:///home/runner/work/PlayGround/PlayGround/index.html', {method:'PUT'}).then(r => r.json());
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((resolve,reject) => { ws.onopen=resolve; ws.onerror=reject; });
  let id=0, pending=new Map(), errors=[];
  ws.onmessage = event => {
    const msg=JSON.parse(event.data);
    if(msg.method==='Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text);
    if(msg.id && pending.has(msg.id)){pending.get(msg.id)(msg);pending.delete(msg.id)}
  };
  const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
  await send('Runtime.enable');
  await send('Page.enable');
  await wait(1200);
  const evaluate=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true})).result.result.value;
  console.log('Initial:', await evaluate("document.title+' | canvas '+document.getElementById('game').width+'x'+document.getElementById('game').height"));
  await evaluate("document.getElementById('play').click()" );
  console.log('Round started:',await evaluate("document.getElementById('phase').textContent+' | '+document.getElementById('buy').className+' | '+document.getElementById('shopgrid').children.length+' shop items'"));
  await evaluate("document.querySelector('#shopgrid button').click()" );
  console.log('Buy action:',await evaluate("document.getElementById('money').textContent.trim()+' | '+document.getElementById('weaponname').textContent"));
  await evaluate("document.getElementById('closebuy').click()" );
  await wait(8000);
  console.log('After prep:',await evaluate("document.getElementById('phase').textContent+' | '+document.getElementById('objective').textContent"));
  console.log('JS exceptions:', errors.length ? errors.join(' | ') : 'none');
  ws.close();
})().catch(error=>{console.error(error);process.exit(1)});

