const fs=require('fs');
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const tab = await fetch('http://127.0.0.1:9222/json/new?file:///home/runner/work/PlayGround/PlayGround/index.html', {method:'PUT'}).then(r => r.json());
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((resolve,reject) => { ws.onopen=resolve; ws.onerror=reject; });
  let id=0, pending=new Map(), errors=[];
  ws.onmessage = event => { const msg=JSON.parse(event.data); if(msg.method==='Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text); if(msg.id&&pending.has(msg.id)){pending.get(msg.id)(msg);pending.delete(msg.id)} };
  const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
  await send('Runtime.enable'); await send('Page.enable'); await wait(700);
  const evaluate=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true})).result.result.value;
  await evaluate("document.getElementById('play').click()");
  console.log('Round start:',await evaluate("document.getElementById('phase').textContent+' / '+document.getElementById('shopgrid').children.length+' items'"));
  await evaluate("document.querySelectorAll('#shopgrid button')[3].click()");
  console.log('Vest purchase:',await evaluate("document.getElementById('money').textContent.trim()+' / '+document.getElementById('armor').textContent"));
  await evaluate("document.getElementById('siteB').click(); document.getElementById('closebuy').click(); prep=0; player.x=sites.B.x; player.y=sites.B.y; update(.01); interact()");
  console.log('Plant interaction:',await evaluate("phase+' / '+document.getElementById('objective').textContent"));
  await evaluate("update(1.7)");
  console.log('Plant completes:',await evaluate("phase+' / '+(bomb?'bomb at '+Math.round(bomb.x)+','+Math.round(bomb.y):'no bomb')"));
  const shot=await send('Page.captureScreenshot',{format:'png'}); fs.writeFileSync('/tmp/opencode/brickops-gameplay.png',Buffer.from(shot.result.data,'base64'));
  await evaluate("bomb.timer=.01; update(.04)");
  console.log('Bomb resolution:',await evaluate("phase+' / '+document.getElementById('endtag').textContent"));
  console.log('JS exceptions:', errors.length ? errors.join(' | ') : 'none');
  ws.close();
})().catch(error=>{console.error(error);process.exit(1)});
